659	/// Real, newly-discovered financial-correctness bug found via mutation testing during a fresh
660	/// spec re-verification: `normalize_model_key`'s progressively-shorter-prefix search let
661	/// "gpt-4o-mini" match the seeded "gpt-4o" key by stripping the trailing "mini" segment.
662	/// "gpt-4o-mini" is a REAL, DIFFERENT, materially cheaper OpenAI model (~$0.15/$0.60 per M vs
663	/// gpt-4o's $2.50/$10.00 per M) -- normalizing it onto gpt-4o's rate is a real ~17x overcharge
664	/// for any Codex/Claude session that reports this model string. The fix restricts what
665	/// `normalize_model_key` may strip to segments that are clearly version/date/scale markers
666	/// (numeric-only segments, digit+single-letter parameter-scale segments like "32b", and a small
667	/// allowlist of non-differentiating tuning words), so "mini" -- which denotes a genuinely
668	/// different priced product, not a version/scale suffix -- can never be stripped. Since no
669	/// seeded key matches after only stripping safe segments, "gpt-4o-mini" must fall through to
670	/// the CRIT-LUMEN-008 unrecognized-model Sonnet fallback, NOT gpt-4o's rate.
671	#[test]
672	fn test_gpt_4o_mini_does_not_normalize_to_gpt_4o() {
673	    let table = PricingTable::seed();
674	    let as_of = Utc.with_ymd_and_hms(2024, 11, 1, 0, 0, 0).unwrap();
675	
676	    let mini_rate = table.rate_for("gpt-4o-mini", None, TokenRateKind::Input, as_of);
677	    let gpt4o_rate = table.rate_for("gpt-4o", None, TokenRateKind::Input, as_of);
678	
679	    assert!((gpt4o_rate - 2.50).abs() < 1e-9, "sanity: gpt-4o's own seeded Input rate must still be $2.50/M");
680	    assert!(
681	        (mini_rate - 2.50).abs() > 1e-9,
682	        "gpt-4o-mini must NOT be billed at gpt-4o's $2.50/M rate -- it is a distinct, much \
683	         cheaper real model"
684	    );
685	    assert!(!table.is_recognized("gpt-4o-mini"));
686	    assert_eq!(
687	        mini_rate, 0.0,
688	        "gpt-4o-mini is unrecognized after normalization (no seeded key matches once \"mini\" is \
689	         correctly rejected as strippable), so it must price at 0.0 (explicitly unpriced), not a \
690	         substituted rate, got {mini_rate}"
691	    );
692	}
