78	    pub fn list_recent(&self, filter: &SessionFilter) -> Result<Vec<SessionSummaryReadModel>, StoreError> {
79	        let limit = if filter.limit > 0 { filter.limit } else { 50 };
80	
81	        let mut stmt = self
82	            .conn
83	            .prepare(
84	                "SELECT id, provider, provider_session_id, model_family, turn_count,
85	                        wall_duration_ms, cache_hit_ratio, total_cost_usd, net_savings_usd, created_at
86	                 FROM sessions
87	                 WHERE (?1 IS NULL OR provider = ?1)
88	                 ORDER BY started_at DESC
89	                 LIMIT ?2",
90	            )
91	            .map_err(StoreError::Sqlite)?;
92	
93	        let rows = stmt
94	            .query_map(params![filter.provider.as_deref(), limit as i64], |row| {
95	                let wall_ms: i64 = row.get(5)?;
96	                let turns: i64 = row.get(4)?;
97	                Ok(SessionSummaryReadModel {
98	                    id: row.get(0)?,
99	                    provider: row.get(1)?,
100	                    session_id: row.get(2)?,
101	                    model_family: row.get(3)?,
102	                    turn_count: turns as usize,
103	                    wall_duration_ms: wall_ms as u64,
104	                    cache_hit_ratio: row.get(6)?,
105	                    total_cost_usd: row.get(7)?,
106	                    net_savings_usd: row.get(8)?,
107	                    created_at: row.get(9)?,
108	                })
109	            })
110	            .map_err(StoreError::Sqlite)?;
111	
112	        let mut result = Vec::new();
113	        for r in rows {
114	            result.push(r.map_err(StoreError::Sqlite)?);
115	        }
116	        Ok(result)
117	    }
