119	    pub fn get_session(&self, provider: &str, session_id: &str) -> Result<Option<SessionDetailReadModel>, StoreError> {
120	        let mut stmt = self
121	            .conn
122	            .prepare(
123	                "SELECT id, provider, provider_session_id, model_family, turn_count,
124	                        wall_duration_ms, cache_hit_ratio, total_cost_usd, net_savings_usd, baseline_cost_usd,
125	                        efficiency_multiplier, created_at
126	                 FROM sessions
127	                 WHERE provider = ?1 AND provider_session_id = ?2",
128	            )
129	            .map_err(StoreError::Sqlite)?;
130	
131	        let mut rows = stmt
132	            .query_map(params![provider, session_id], |row| {
133	                let id: i64 = row.get(0)?;
134	                let provider: String = row.get(1)?;
135	                let sess_id: String = row.get(2)?;
136	                let model_family: String = row.get(3)?;
137	                let turns: i64 = row.get(4)?;
138	                let wall_ms: i64 = row.get(5)?;
139	                let cache_hit: f32 = row.get(6)?;
140	                let cost_usd: f64 = row.get(7)?;
141	                let savings_usd: f64 = row.get(8)?;
142	                let baseline_usd: f64 = row.get(9)?;
143	                let efficiency: f32 = row.get(10)?;
144	                let created_at = row.get(11)?;
145	
146	                Ok((
147	                    id,
148	                    SessionDetailReadModel {
149	                        summary: SessionSummaryReadModel {
150	                            id,
151	                            provider,
152	                            session_id: sess_id,
153	                            model_family: model_family.clone(),
154	                            turn_count: turns as usize,
155	                            wall_duration_ms: wall_ms as u64,
156	                            cache_hit_ratio: cache_hit,
157	                            total_cost_usd: cost_usd,
158	                            net_savings_usd: savings_usd,
159	                            created_at,
160	                        },
161	                        economics: TokenEconomics {
162	                            input_tokens: 0,
163	                            output_tokens: 0,
164	                            cache_creation_tokens: 0,
165	                            cache_read_tokens: 0,
166	                            ephemeral_5m_tokens: 0,
167	                            ephemeral_1h_tokens: 0,
168	                            cache_hit_ratio: cache_hit,
169	                            total_cost_usd: cost_usd,
170	                            provided_cost_usd: None,
171	                            baseline_cost_no_cache_usd: baseline_usd,
172	                            net_savings_usd: savings_usd,
173	                            efficiency_multiplier: efficiency,
174	                            per_model: std::collections::HashMap::new(),
175	                            reasoning_output_tokens: 0,
176	                            // Not yet a persisted column -- same pre-existing read-back gap as
177	                            // reasoning_tokens above.
