179	                        },
180	                        tool_counts: BTreeMap::new(),
181	                        error_counts: BTreeMap::new(),
182	                    },
183	                ))
184	            })
185	            .map_err(StoreError::Sqlite)?;
186	
187	        let next_row = if let Some(res) = rows.next() { Some(res.map_err(StoreError::Sqlite)?) } else { None };
188	        drop(rows);
189	        drop(stmt);
190	
191	        let (id, mut detail) = match next_row {
192	            Some(pair) => pair,
193	            None => return Ok(None),
194	        };
195	
196	        let tool_call_repo = ToolCallRepository::new(self.conn);
197	        detail.tool_counts = tool_call_repo.tool_counts_by_session(id)?;
198	        detail.error_counts = tool_call_repo.error_counts_by_session(id)?;
199	
200	        let token_usage_repo = TokenUsageRepository::new(self.conn);
201	        let per_model = token_usage_repo.per_model_by_session(id)?;
202	
203	        let mut input_tokens = 0u64;
204	        let mut output_tokens = 0u64;
205	        let mut cache_creation_tokens = 0u64;
